def renderizar_tab_asientos_ventas(db_connection):
    st.subheader("🤖 Asientos Automatizados - Libro de Ventas")
    st.markdown("""
    Sube tu **Libro de Ventas** en Excel. El sistema procesará los datos, consultará la tabla de clientes comerciales por RIF y generará los asientos contables correspondientes.
    """)

    # ----------------------------------------------------
    # VALIDACIÓN DE ROL Y FILTRADO DE EMPRESAS
    # ----------------------------------------------------
    usuario_actual = str(
        st.session_state.get("user", st.session_state.get("usuario", "norbe"))
    ).strip()

    rol_usuario = "cliente"
    es_admin = False
    db_asignada_usuario = ""

    dbs_filtradas = []
    mapa_nombres_empresas = {}

    try:
        with db_connection.cursor(pymysql.cursors.DictCursor) as cursor_temp:
            cursor_temp.execute(
                "SELECT rol, db_nombre FROM control_central.usuarios WHERE usuario = %s",
                (usuario_actual,),
            )
            res_usuario = cursor_temp.fetchone()

            if res_usuario:
                rol_usuario = str(res_usuario.get("rol", "cliente")).strip().lower()
                db_asignada_usuario = str(
                    res_usuario.get("db_nombre", "")
                ).strip()

            es_admin = rol_usuario in [
                "admin",
                "administrador",
            ] or st.session_state.get("es_admin", False)

            cursor_temp.execute("SELECT * FROM control_central.clientes")
            clientes_db = cursor_temp.fetchall()

        for cli in clientes_db:
            db_name = str(cli.get("db_nombre", "")).strip()
            nombre_comercial = str(cli.get("nombre_empresa", db_name)).strip()

            if db_name:
                if es_admin:
                    dbs_filtradas.append(db_name)
                    mapa_nombres_empresas[db_name] = nombre_comercial
                else:
                    if (
                        db_asignada_usuario
                        and db_name.lower() == db_asignada_usuario.lower()
                    ):
                        dbs_filtradas.append(db_name)
                        mapa_nombres_empresas[db_name] = nombre_comercial

    except Exception as e:
        st.warning(f"⚠️ Error consultando `control_central`: {e}")
        if es_admin:
            dbs_filtradas = ["kingdirver_ca"]
        else:
            dbs_filtradas = [
                db_asignada_usuario if db_asignada_usuario else "kingkingdirver_cad"
            ]

    if not dbs_filtradas:
        dbs_filtradas = [db_asignada_usuario] if db_asignada_usuario else ["kingdkingdirver_ca"]

    if not dbs_filtradas:
        st.error("⚠️ No se encontró una empresa asignada a tu usuario en la tabla `usuarios`.")
        return

    # ----------------------------------------------------
    # INTERFAZ SEGÚN EL ROL
    # ----------------------------------------------------
    if es_admin:
        st.markdown("### 🏢 Contexto de Empresa (Modo Administrador)")

        index_default = 0
        for i, db_name in enumerate(dbs_filtradas):
            if any(
                k in str(st.session_state).lower()
                and db_name.lower() in str(st.session_state[k]).lower()
                for k in st.session_state
            ):
                index_default = i
                break
            if "driver" in db_name.lower() or "king" in db_name.lower():
                index_default = i

        format_func = lambda db: (
            f"{mapa_nombres_empresas.get(db, db)} ({db})"
            if db in mapa_nombres_empresas
            else db
        )

        nombre_db_cliente = st.selectbox(
            "Selecciona la Base de Datos de la Empresa Activa:",
            dbs_filtradas,
            index=index_default,
            format_func=format_func,
            key="select_db_admin_asientos_ventas",
        )
    else:
        nombre_db_cliente = dbs_filtradas[0]
        nombre_amigable = mapa_nombres_empresas.get(
            nombre_db_cliente, nombre_db_cliente
        )
        st.info(f"🏢 **Empresa Activa:** {nombre_amigable} (`{nombre_db_cliente}`)")

    if not nombre_db_cliente:
        st.error("⚠️ Debes seleccionar una base de datos.")
        return

    db_segura = str(nombre_db_cliente).strip()

    mapa_descripciones = {}
    opciones_desplegable = []

    # ----------------------------------------------------
    # CARGA DE PLAN DE CUENTAS
    # ----------------------------------------------------
    if db_connection:
        try:
            with db_connection.cursor(pymysql.cursors.DictCursor) as cursor_opt:
                cursor_opt.execute(
                    f"SELECT codigo, nombre, tipo FROM `{db_segura}`.plan_cuentas ORDER BY codigo ASC"
                )
                cuentas_opt = cursor_opt.fetchall()

                cuentas_detalle = [
                    c for c in cuentas_opt
                    if str(c.get("tipo", "")).strip().lower() == "detalle"
                ]
                lista_cuentas = cuentas_detalle if cuentas_detalle else cuentas_opt

                for c in lista_cuentas:
                    codigo = str(c.get("codigo", "")).strip()
                    nombre = str(c.get("nombre", "")).strip()
                    if codigo:
                        mapa_descripciones[codigo] = nombre
                        opciones_desplegable.append(codigo)

                if not opciones_desplegable:
                    opciones_desplegable = [
                        "1.1.2.01.001",
                        "4.1.1.01.001",
                        "2.1.2.01.001",
                    ]
                    mapa_descripciones = {
                        "1.1.2.01.001": "Cuentas por Cobrar Comerciales",
                        "4.1.1.01.001": "Ventas de Servicios / Ingresos",
                        "2.1.2.01.001": "IVA Débito Fiscal",
                    }
        except Exception as e:
            st.warning(f"⚠️ Advertencia al consultar plan de cuentas: {e}. Usando cuentas predeterminadas.")
            opciones_desplegable = ["1.1.2.01.001", "4.1.1.01.001", "2.1.2.01.001"]
            mapa_descripciones = {
                "1.1.2.01.001": "Cuentas por Cobrar Comerciales",
                "4.1.1.01.001": "Ventas de Servicios / Ingresos",
                "2.1.2.01.001": "IVA Débito Fiscal",
            }

    # ----------------------------------------------------
    # CARGAR CLIENTES COMERCIALES
    # ----------------------------------------------------
    mapa_clientes_rif = {}
    try:
        with db_connection.cursor(pymysql.cursors.DictCursor) as cursor_cli:
            cursor_cli.execute(
                f"SELECT rif, codigo_cuenta, descripcion_cuenta FROM `{db_segura}`.clientes_comerciales"
            )
            clientes_registrados = cursor_cli.fetchall()
            for cli in clientes_registrados:
                rif_limpio = str(cli.get("rif", "")).strip().upper()
                mapa_clientes_rif[rif_limpio] = {
                    "codigo_cuenta": str(cli.get("codigo_cuenta", "")).strip(),
                    "descripcion_cuenta": str(cli.get("descripcion_cuenta", "")).strip(),
                }
    except Exception as e:
        st.warning(f"⚠️ No se pudo consultar la tabla `clientes_comerciales`: {e}")

    # ----------------------------------------------------
    # FUNCIONES AUXILIARES DE LIMPIEZA
    # ----------------------------------------------------
    def limpiar_y_forzar_numerico(df):
        if df is None or df.empty:
            return df
        for col in df.columns:
            c_lower = str(col).lower().strip()
            keywords = [
                "debe", "haber", "venta", "base", "debito", "crédito", 
                "credito", "total", "iva", "monto", "impuesto", "exenta", 
                "alícuota", "alicuota"
            ]

            if any(term in c_lower for term in keywords) or col in ["debe", "haber"]:
                def parsear_valor_latino(val):
                    if val is None or pd.isna(val) or str(val).strip() in ["", "nan", "None"]:
                        return 0.0
                    if isinstance(val, (int, float)):
                        return float(val)
                    
                    val_str = str(val).strip().replace(" ", "").replace("$", "").replace("Bs.", "")
                    
                    try:
                        return float(val_str)
                    except ValueError:
                        pass

                    try:
                        if "," in val_str and "." in val_str:
                            if val_str.rfind(",") > val_str.rfind("."):
                                val_str = val_str.replace(".", "").replace(",", ".")
                            else:
                                val_str = val_str.replace(",", "")
                        elif "," in val_str:
                            val_str = val_str.replace(".", "").replace(",", ".")
                        elif "." in val_str:
                            partes = val_str.split(".")
                            if len(partes) > 2 or (len(partes) == 2 and len(partes[-1]) != 2):
                                val_str = val_str.replace(".", "")
                        return float(val_str)
                    except Exception:
                        return 0.0

                df[col] = df[col].apply(parsear_valor_latino)
        return df

    def formato_venezolano(val):
        try:
            return f"{float(val):,.2f}".replace(",", "X").replace(".", ",").replace("X", ".")
        except:
            return "0,00"

    # ----------------------------------------------------
    # CARGA Y VISTA PREVIA DEL EXCEL
    # ----------------------------------------------------
    st.markdown("---")
    st.markdown("### 📋 Primer Frame: Libro de Ventas Subido")

    key_uploader_dinamica = f"uploader_libro_ventas_{db_segura}"
    archivo_excel = st.file_uploader(
        "Subir Libro de Ventas (Excel)",
        type=["xlsx", "xls"],
        key=key_uploader_dinamica,
    )

    if archivo_excel is not None:
        try:
            df_ventas = pd.read_excel(archivo_excel, dtype=str)
            df_ventas.columns = df_ventas.columns.str.strip()
            
            # GARANTIZAR NOMBRES DE COLUMNAS ÚNICOS
            cols_vistas = []
            nuevas_cols = []
            for c in df_ventas.columns:
                c_str = str(c)
                if c_str in cols_vistas:
                    i = 1
                    while f"{c_str}_{i}" in cols_vistas:
                        i += 1
                    c_str = f"{c_str}_{i}"
                cols_vistas.append(c_str)
                nuevas_cols.append(c_str)
            df_ventas.columns = nuevas_cols

            df_ventas = limpiar_y_forzar_numerico(df_ventas)

            df_ventas_visual = df_ventas.copy()
            for col in df_ventas_visual.columns:
                c_lower = str(col).lower().strip()
                es_total_ventas = "total" in c_lower and "venta" in c_lower
                es_ventas_exentas = "exenta" in c_lower and "venta" in c_lower
                
                if es_total_ventas or es_ventas_exentas or "base" in c_lower or "debito" in c_lower:
                    df_ventas_visual[col] = df_ventas_visual[col].apply(formato_venezolano)

            configuracion_columnas_dataframe = {}
            for col in df_ventas.columns:
                c_lower = str(col).lower().strip()
                es_total_ventas = "total" in c_lower and "venta" in c_lower
                es_ventas_exentas = "exenta" in c_lower and "venta" in c_lower
                
                if es_total_ventas or es_ventas_exentas or "base" in c_lower or "debito" in c_lower:
                    configuracion_columnas_dataframe[col] = (
                        st.column_config.TextColumn(str(col))
                    )

            st.dataframe(
                df_ventas_visual,
                use_container_width=True,
                column_config=configuracion_columnas_dataframe,
            )

            st.markdown("---")
            st.markdown("### ⚙️ Configuración de Asientos de Ventas")

            col_cfg1, col_cfg2 = st.columns(2)
            with col_cfg1:
                n_comprobante_base = st.text_input(
                    "Número de Comprobante (Fijo para todas las líneas):",
                    value="050001",
                    key=f"prefijo_ventas_{db_segura}",
                )

            if st.button(
                "🔄 Generar Estructura del Segundo Frame (Ventas)",
                key=f"btn_generar_frame_ventas_{db_segura}",
            ):
                try:
                    filas_asiento_temporal = []

                    # ----------------------------------------------------
                    # MAPEO DE COLUMNAS FUERA DEL BUCLE (OPTIMIZACIÓN O(1))
                    # ----------------------------------------------------
                    def encontrar_columna(posibles_nombres):
                        for col in df_ventas.columns:
                            c_clean = str(col).strip().lower()
                            for pos in posibles_nombres:
                                if pos.lower() in c_clean:
                                    return col
                        return None

                    col_fecha = encontrar_columna(["Fecha de Factura", "Fecha"])
                    col_razon = encontrar_columna(["Nombre y Apellido o Razón Social", "Razon Social", "Cliente"])
                    col_rif = encontrar_columna(["R.I.F.", "RIF", "Rif"])
                    
                    col_factura = None
                    for col in df_ventas.columns:
                        c_clean = str(col).strip().lower()
                        if ("factura" in c_clean or "nro" in c_clean or "num" in c_clean) and "fecha" not in c_clean:
                            col_factura = col
                            break

                    col_exentas = encontrar_columna(["Ventas Exentas", "Exentas"])
                    col_base = encontrar_columna(["Base Imponible"])
                    col_debito = encontrar_columna(["Débito Fiscal", "Debito Fiscal"])
                    col_total = encontrar_columna(["Total Ventas Incluyendo el IVA", "Total Ventas"])

                    # ----------------------------------------------------
                    # INICIALIZACIÓN SEGURA DE VARIABLES CLAVE
                    # ----------------------------------------------------
                    default_opcion = opciones_desplegable[0] if 'opciones_desplegable' in locals() and opciones_desplegable else ""

                    # ----------------------------------------------------
                    # BUCLE DE PROCESAMIENTO ULTRARRÁPIDO
                    # ----------------------------------------------------
                    for idx, row in df_ventas.iterrows():
                        # 1. Fecha
                        raw_fecha = row[col_fecha] if col_fecha else ""
                        if hasattr(raw_fecha, "strftime"):
                            fecha_op = raw_fecha.strftime("%Y-%m-%d")
                        else:
                            val_str = str(raw_fecha).strip().split(" ")[0]
                            try:
                                fecha_op = pd.to_datetime(val_str).strftime("%Y-%m-%d")
                            except Exception:
                                fecha_op = val_str[:10] if val_str else ""

                        # 2. Razón Social y RIF
                        razon_social = str(row[col_razon] if col_razon and pd.notna(row[col_razon]) else "Sin Nombre").strip()
                        rif_cliente = str(row[col_rif] if col_rif and pd.notna(row[col_rif]) else "").strip().upper()

                        # 3. Número de Documento
                        nro_doc = ""
                        if col_factura and pd.notna(row[col_factura]):
                            val = row[col_factura]
                            if isinstance(val, pd.Series):
                                val = val.iloc[0]
                            nro_doc = str(val).strip()
                        if not nro_doc:
                            nro_doc = str(idx + 1)

                        # 4. Montos Numéricos
                        try:
                            ventas_exentas = float(row[col_exentas]) if col_exentas and pd.notna(row[col_exentas]) else 0.0
                        except Exception:
                            ventas_exentas = 0.0

                        try:
                            base_imponible = float(row[col_base]) if col_base and pd.notna(row[col_base]) else 0.0
                        except Exception:
                            base_imponible = 0.0

                        try:
                            debito_fiscal = float(row[col_debito]) if col_debito and pd.notna(row[col_debito]) else 0.0
                        except Exception:
                            debito_fiscal = 0.0

                        try:
                            total_ventas = float(row[col_total]) if col_total and pd.notna(row[col_total]) else (base_imponible + ventas_exentas + debito_fiscal)
                        except Exception:
                            total_ventas = base_imponible + ventas_exentas + debito_fiscal

                        n_comprobante_actual = str(n_comprobante_base).strip()
                        opcion_cxc = default_opcion
                        descripcion_personalizada = f"Factura Venta {nro_doc} - {razon_social}"

                        if rif_cliente in mapa_clientes_rif:
                            info_cli = mapa_clientes_rif[rif_cliente]
                            if info_cli["codigo_cuenta"]:
                                opcion_cxc = info_cli["codigo_cuenta"]
                            if info_cli["descripcion_cuenta"]:
                                descripcion_personalizada = info_cli["descripcion_cuenta"]

                        opcion_ingreso = default_opcion
                        opcion_iva_debito = default_opcion

                        for opt in opciones_desplegable:
                            if opt.startswith("4"):
                                opcion_ingreso = opt
                                break
                        for opt in opciones_desplegable:
                            if "2.1.2" in opt or "debito" in mapa_descripciones.get(opt, "").lower():
                                opcion_iva_debito = opt
                                break

                        # 1. Cuentas por Cobrar (DEBE)
                        filas_asiento_temporal.append({
                            "n_comprobante": n_comprobante_actual,
                            "descripcion": descripcion_personalizada,
                            "fecha": fecha_op,
                            "plan_cuentas": opcion_cxc,
                            "cuenta_contable": mapa_descripciones.get(opcion_cxc, ""),
                            "referencia": nro_doc,
                            "debe": formato_venezolano(float(total_ventas)),
                            "haber": formato_venezolano(0.0),
                        })

                        # 2. Ingresos (HABER)
                        monto_ingreso = float(base_imponible + ventas_exentas)
                        if monto_ingreso > 0:
                            filas_asiento_temporal.append({
                                "n_comprobante": n_comprobante_actual,
                                "descripcion": f"Ingresos por Ventas Factura {nro_doc} - {razon_social}",
                                "fecha": fecha_op,
                                "plan_cuentas": opcion_ingreso,
                                "cuenta_contable": mapa_descripciones.get(opcion_ingreso, ""),
                                "referencia": nro_doc,
                                "debe": formato_venezolano(0.0),
                                "haber": formato_venezolano(monto_ingreso),
                            })

                        # 3. IVA Débito Fiscal (HABER)
                        if debito_fiscal > 0:
                            filas_asiento_temporal.append({
                                "n_comprobante": n_comprobante_actual,
                                "descripcion": f"IVA Débito Fiscal Factura {nro_doc} - {razon_social}",
                                "fecha": fecha_op,
                                "plan_cuentas": opcion_iva_debito,
                                "cuenta_contable": mapa_descripciones.get(opcion_iva_debito, ""),
                                "referencia": nro_doc,
                                "debe": formato_venezolano(0.0),
                                "haber": formato_venezolano(float(debito_fiscal)),
                            })

                    df_nuevo = pd.DataFrame(filas_asiento_temporal)
                    st.session_state["df_asientos_ventas_proceso"] = df_nuevo
                    st.rerun()

                except Exception as proc_err:
                    st.error(f"Error procesando los datos de ventas: {proc_err}")
        except Exception as excel_err:
            st.error(f"Error al leer o procesar el archivo Excel: {excel_err}")

    # ----------------------------------------------------
    # SEGUNDO FRAME: ESTRUCTURA COMPLETA DE VENTAS (OPTIMIZADO)
    # ----------------------------------------------------
    if 'df_asientos_ventas_proceso' in st.session_state and not st.session_state['df_asientos_ventas_proceso'].empty:
        df_a_procesar = st.session_state['df_asientos_ventas_proceso'].copy()
        
        st.markdown(f"### 📋 Segundo Frame: Estructura del Asiento de Ventas ({len(df_a_procesar)} registros)")
        
        # 1. Limpieza vectorizada rápida de Debe y Haber
        for col in ['debe', 'haber']:
            if col in df_a_procesar.columns:
                df_a_procesar[col] = (
                    df_a_procesar[col]
                    .astype(str)
                    .str.replace('$', '', regex=False)
                    .str.replace('€', '', regex=False)
                    .str.replace('.', '', regex=False)
                    .str.replace(',', '.', regex=False)
                    .str.strip()
                )
                df_a_procesar[col] = pd.to_numeric(df_a_procesar[col], errors='coerce').fillna(0.0)

        if 'mapa_descripciones' not in locals() and 'mapa_descripciones' not in globals():
            mapa_descripciones = {} 
        
        mapa_descripciones["4.1.1.01.001"] = "Ingresos Exento I.V.A."

        def formato_venezolano(val):
            try:
                return f"{float(val):,.2f}".replace(",", "X").replace(".", ",").replace("X", ".")
            except Exception:
                return "0,00"

        def extraer_solo_codigo(val):
            val_str = str(val).strip()
            return val_str.split(" - ")[0].strip() if " - " in val_str else val_str

        # 2. OPTIMIZACIÓN CLAVE: Cargar clientes comerciales UNA SOLA VEZ en memoria
        lista_clientes_comerciales = []
        try:
            with db_connection.cursor() as cur_cc:
                cur_cc.execute(f"SELECT codigo_cuenta, descripcion_cuenta, rif, razon_social FROM `{db_segura}`.clientes_comerciales;")
                lista_clientes_comerciales = cur_cc.fetchall()
        except Exception as e:
            print(f"Error cargando clientes_comerciales: {e}")

        def buscar_cliente_en_memoria(texto_fila):
            if not texto_fila or str(texto_fila).strip() in ["", "nan", "None"]:
                return None, None, None
            texto_upper = str(texto_fila).upper()
            for codigo_cta, desc_cta, rif_cli, razon in lista_clientes_comerciales:
                if (razon and str(razon).upper() in texto_upper) or (desc_cta and str(desc_cta).upper() in texto_upper):
                    return str(codigo_cta).strip(), str(desc_cta).strip(), str(rif_cli).strip()
            return None, None, None

        # 3. Asignación rápida de cuentas usando la búsqueda en memoria
        for idx in df_a_procesar.index:
            desc_actual = str(df_a_procesar.at[idx, "descripcion"]) if "descripcion" in df_a_procesar.columns else ""
            cod_cliente, desc_cliente, rif_oficial = buscar_cliente_en_memoria(desc_actual)
            
            haber_val = float(df_a_procesar.at[idx, "haber"]) if "haber" in df_a_procesar.columns else 0.0
            debe_val = float(df_a_procesar.at[idx, "debe"]) if "debe" in df_a_procesar.columns else 0.0

            if haber_val > 0 and debe_val == 0:
                df_a_procesar.at[idx, "plan_cuentas"] = "4.1.1.01.001"
            else:
                if cod_cliente:
                    df_a_procesar.at[idx, "plan_cuentas"] = cod_cliente
                    if cod_cliente not in mapa_descripciones and desc_cliente:
                        mapa_descripciones[cod_cliente] = desc_cliente

            if rif_oficial and rif_oficial not in desc_actual and " - RIF:" not in desc_actual:
                df_a_procesar.at[idx, "descripcion"] = f"{desc_actual} - RIF: {rif_oficial}"

            codigo_actual = extraer_solo_codigo(df_a_procesar.at[idx, "plan_cuentas"])
            if codigo_actual == "4.1.1.01.001":
                df_a_procesar.at[idx, "cuenta_contable"] = "Ingresos Exento I.V.A."
            else:
                df_a_procesar.at[idx, "cuenta_contable"] = mapa_descripciones.get(codigo_actual, desc_cliente or "")

        opciones_codigos_puros = list(mapa_descripciones.keys())
        if not opciones_codigos_puros or "4.1.1.01.001" not in opciones_codigos_puros:
            opciones_codigos_puros = ["4.1.1.01.001"] + [op for op in opciones_codigos_puros if op != "4.1.1.01.001"]

        # 4. Preparar visualización
        df_para_mostrar = df_a_procesar.copy()
        for col in ['debe', 'haber']:
            if col in df_para_mostrar.columns:
                df_para_mostrar[col] = pd.to_numeric(df_para_mostrar[col], errors='coerce').fillna(0.0)
                df_para_mostrar[col] = df_para_mostrar[col].apply(formato_venezolano)

        df_editado_crudo = st.data_editor(
            df_para_mostrar,
            num_rows="dynamic",
            use_container_width=True,
            column_config={
                "n_comprobante": st.column_config.TextColumn("n_comprobante"),
                "descripcion": st.column_config.TextColumn("Descripción (Incluye RIF)"),
                "fecha": st.column_config.TextColumn("Fecha"),
                "plan_cuentas": st.column_config.SelectboxColumn(
                    "Plan de Cuentas (Cliente o Ingreso Exento)",
                    options=opciones_codigos_puros,
                    required=True
                ),
                "cuenta_contable": st.column_config.TextColumn("Descripción Cuenta", disabled=True),
                "referencia": st.column_config.TextColumn("Referencia"),
                "debe": st.column_config.TextColumn("Debe"),
                "haber": st.column_config.TextColumn("Haber"),
            },
            key="editor_segundo_frame_ventas"
        )
        
        # 5. Re-conversión a numéricos
        df_editado = df_editado_crudo.copy()
        for col in ['debe', 'haber']:
            if col in df_editado.columns:
                col_limpia = (
                    df_editado[col]
                    .astype(str)
                    .str.replace('$', '', regex=False)
                    .str.replace('.', '', regex=False)
                    .str.replace(',', '.', regex=False)
                    .str.strip()
                )
                df_editado[col] = pd.to_numeric(col_limpia, errors='coerce').fillna(0.0).astype(float)

        for idx in df_editado.index:
            codigo_puro = extraer_solo_codigo(df_editado.at[idx, "plan_cuentas"])
            df_editado.at[idx, "plan_cuentas"] = codigo_puro
            if codigo_puro == "4.1.1.01.001":
                df_editado.at[idx, "cuenta_contable"] = "Ingresos Exento I.V.A."
            else:
                df_editado.at[idx, "cuenta_contable"] = mapa_descripciones.get(codigo_puro, "")

        st.session_state['df_asientos_proceso'] = df_editado
        
        tot_debe = float(df_editado['debe'].sum())
        tot_haber = float(df_editado['haber'].sum())
        
        col_m1, col_m2 = st.columns(2)
        col_m1.metric("Total Debe (Ventas)", formato_venezolano(tot_debe))
        col_m2.metric("Total Haber (Ventas)", formato_venezolano(tot_haber))

        buffer_excel = io.BytesIO()
        with pd.ExcelWriter(buffer_excel, engine='openpyxl') as writer:
            df_editado.to_excel(writer, index=False, sheet_name='Asientos_Ventas')
        buffer_excel.seek(0)

        st.download_button(
            label="📥 Descargar Estructura de Ventas en Excel",
            data=buffer_excel,
            file_name=f"asientos_ventas_{db_segura}.xlsx",
            mime="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
            key="btn_descargar_excel_ventas",
            use_container_width=False
        )

        if st.button("💾 Guardar Asientos de Ventas en el Libro Diario", key="btn_guardar_ventas_finales", use_container_width=False):
            try:
                df_val = df_editado.copy()
                df_val['fecha'] = pd.to_datetime(df_val['fecha'], errors='coerce')
                anios_meses_excel = set((row['fecha'].year, row['fecha'].month) for _, row in df_val.iterrows() if pd.notnull(row['fecha']))
                
                bloqueo_detectado = False
                mensaje_bloqueo = ""
                
                for anio, mes in anios_meses_excel:
                    try:
                        with db_connection.cursor() as cur_check:
                            cur_check.execute(f"""
                                SELECT COUNT(*) FROM `{db_segura}`.asientos_contables 
                                WHERE YEAR(fecha) = %s AND MONTH(fecha) = %s AND bloqueado = 1
                            """, (anio, mes))
                            res_bloqueo = cur_check.fetchone()
                            
                            if res_bloqueo and res_bloqueo[0] > 0:
                                bloqueo_detectado = True
                                mensaje_bloqueo = f"❌ **Operación Denegada**: El período correspondiente al mes **{mes:02d}/{anio}** se encuentra **CERRADO y BLOQUEADO**."
                                break
                    except Exception:
                        pass

                if bloqueo_detectado:
                    st.error(mensaje_bloqueo)
                else:
                    with db_connection.cursor() as cursor:
                        # 1. Crear tabla de asientos contables si no existe
                        cursor.execute(f"""
                            CREATE TABLE IF NOT EXISTS `{db_segura}`.asientos_contables (
                                id INT AUTO_INCREMENT PRIMARY KEY,
                                n_comprobante VARCHAR(50),
                                descripcion TEXT,
                                fecha DATE,
                                plan_cuentas VARCHAR(100),
                                cuenta_contable VARCHAR(255),
                                referencia VARCHAR(100),
                                debe DECIMAL(15, 2) DEFAULT 0.00,
                                haber DECIMAL(15, 2) DEFAULT 0.00,
                                bloqueado TINYINT DEFAULT 0
                            );
                        """)
                        
                        # 2. Crear tabla de órdenes de cobranza si no existe (con la estructura solicitada)
                        cursor.execute(f"""
                            CREATE TABLE IF NOT EXISTS `{db_segura}`.ordenes_cobranza (
                                id INT AUTO_INCREMENT PRIMARY KEY,
                                empresa_db VARCHAR(50),
                                rif_cliente VARCHAR(20),
                                n_factura VARCHAR(50),
                                n_control VARCHAR(50),
                                fecha_emision DATE,
                                base_imponible DECIMAL(18,2),
                                monto_exento DECIMAL(18,2),
                                porcentaje_alicuota DECIMAL(5,2),
                                monto_iva DECIMAL(18,2),
                                monto_bruto DECIMAL(18,2),
                                estado_cobro VARCHAR(50) DEFAULT 'PENDIENTE',
                                referencia_banco VARCHAR(100),
                                banco_receptor VARCHAR(100),
                                fecha_registro TIMESTAMP DEFAULT CURRENT_TIMESTAMP
                            );
                        """)
                        
                        # 3. Preparar listas para inserción masiva
                        datos_asientos = []
                        datos_cobranzas = []
                        
                        for _, row in df_editado.iterrows():
                            codigo_limpio = extraer_solo_codigo(row["plan_cuentas"])
                            fecha_str = str(row["fecha"]).split(" ")[0] if pd.notnull(row["fecha"]) else None
                            ref_val = str(row["referencia"]) if pd.notnull(row["referencia"]) else ""
                            
                            # Datos para Asientos Contables
                            datos_asientos.append((
                                str(row["n_comprobante"]),
                                str(row["descripcion"]),
                                fecha_str,
                                str(codigo_limpio),
                                str(row["cuenta_contable"]),
                                ref_val,
                                float(row["debe"]),
                                float(row["haber"])
                            ))
                            
                            # Datos para Órdenes de Cobranza (Validando que las columnas existan en tu DataFrame de ventas)
                            # Ajusta los nombres de las columnas del DataFrame de ventas si se llaman ligeramente diferente (ej. 'rif', 'base_imponible', etc.)
                            rif_cli = str(row.get("rif", row.get("rif_cliente", "")))
                            n_fact = str(row.get("n_factura", row.get("numero_factura", "")))
                            n_ctrl = str(row.get("n_control", row.get("numero_control", "")))
                            base_imp = float(row.get("base_imponible", 0.0))
                            m_exento = float(row.get("monto_exento", row.get("importe_exento", 0.0)))
                            p_alic = float(row.get("porcentaje_alicuota", 16.0)) # Alicuota por defecto 16% o la que venga
                            m_iva = float(row.get("monto_iva", row.get("iva_monto", 0.0)))
                            m_bruto = float(row.get("monto_bruto", row.get("total_compras", row.get("total", 0.0))))
                            
                            datos_cobranzas.append((
                                str(db_segura),
                                rif_cli,
                                n_fact,
                                n_ctrl,
                                fecha_str,
                                base_imp,
                                m_exento,
                                p_alic,
                                m_iva,
                                m_bruto,
                                'PENDIENTE' # Estado inicial por cobrar
                            ))
                        
                        # 4. Inserción de Asientos Contables
                        sql_insert_asientos = f"""
                            INSERT INTO `{db_segura}`.asientos_contables 
                            (n_comprobante, descripcion, fecha, plan_cuentas, cuenta_contable, referencia, debe, haber, bloqueado)
                            VALUES (%s, %s, %s, %s, %s, %s, %s, %s, 0)
                        """
                        cursor.executemany(sql_insert_asientos, datos_asientos)
                        
                        # 5. Inserción de Órdenes de Cobranza (Evitando duplicados exactos por factura y cliente si ya existían)
                        sql_insert_cobranza = f"""
                            INSERT INTO `{db_segura}`.ordenes_cobranza 
                            (empresa_db, rif_cliente, n_factura, n_control, fecha_emision, base_imponible, monto_exento, porcentaje_alicuota, monto_iva, monto_bruto, estado_cobro)
                            VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
                            ON DUPLICATE KEY UPDATE 
                                base_imponible = VALUES(base_imponible),
                                monto_iva = VALUES(monto_iva),
                                monto_bruto = VALUES(monto_bruto)
                        """
                        cursor.executemany(sql_insert_cobranza, datos_cobranzas)
                        
                        db_connection.commit()
                        
                        st.success(f"✅ ¡{len(datos_asientos)} asientos de ventas y sus órdenes de cobranza fueron guardados correctamente en `{db_segura}`!")

            except Exception as db_err:
                if hasattr(db_connection, 'rollback'):
                    db_connection.rollback()
                st.error(f"❌ Error crítico al guardar en MySQL: {str(db_err)}")



def cobranzas_facutras(conn):
    st.markdown("### 💳 Conciliación, Cruce Bancario y Cobranza de Facturas (Abonos y Cuotas)")
    st.markdown("Cruza órdenes de cobranza por montos totales o cuotas parciales, regístralas en el banco y mantén el control de saldos pendientes.")

    db_actual = st.session_state.get('DB_ACTUAL')
    if not db_actual:
        st.warning("⚠️ Selecciona una empresa para gestionar las cobranzas.")
        return

    try:
        @st.cache_data(ttl=300, show_spinner=False)
        def cargar_datos_cobranza_opt(empresa):
            b_lista, b_dict = [], {}
            cxc_lista, cxc_dict = [], {}
            df_cob_pend = None
            df_cob_conciliadas = None
            conn_c = None
            try:
                conn_c = conectar_db(empresa)
                if conn_c:
                    # 1. Cuentas Banco / Caja (Debe)
                    df_ctas = ejecutar_consulta(
                        "SELECT codigo, nombre FROM plan_cuentas WHERE tipo = 'Detalle' AND (codigo LIKE '1.1.1%%' OR codigo LIKE '1.1.2%%' OR LOWER(nombre) LIKE '%%banco%%' OR LOWER(nombre) LIKE '%%caja%%') ORDER BY codigo", 
                        conn_c
                    )
                    if df_ctas is None or df_ctas.empty:
                        df_ctas = ejecutar_consulta("SELECT codigo, nombre FROM plan_cuentas WHERE tipo = 'Detalle' ORDER BY codigo", conn_c)
                    
                    if df_ctas is not None and not df_ctas.empty:
                        for _, r_cta in df_ctas.iterrows():
                            lbl_cta = f"{str(r_cta['codigo']).strip()} - {str(r_cta['nombre']).strip()}"
                            b_lista.append(lbl_cta)
                            b_dict[lbl_cta] = {'codigo': str(r_cta['codigo']).strip(), 'nombre': str(r_cta['nombre']).strip()}

                    # 2. Cuentas por Cobrar / Clientes (Haber)
                    df_cxc = ejecutar_consulta(
                        "SELECT codigo, nombre FROM plan_cuentas WHERE tipo = 'Detalle' AND (codigo LIKE '1.1.3%%' OR LOWER(nombre) LIKE '%%cobrar%%' OR LOWER(nombre) LIKE '%%cliente%%') ORDER BY codigo", 
                        conn_c
                    )
                    if df_cxc is None or df_cxc.empty:
                        df_cxc = ejecutar_consulta("SELECT codigo, nombre FROM plan_cuentas WHERE tipo = 'Detalle' ORDER BY codigo", conn_c)

                    if df_cxc is not None and not df_cxc.empty:
                        for _, r_cxc in df_cxc.iterrows():
                            lbl_cxc = f"{str(r_cxc['codigo']).strip()} - {str(r_cxc['nombre']).strip()}"
                            cxc_lista.append(lbl_cxc)
                            cxc_dict[lbl_cxc] = {'codigo': str(r_cxc['codigo']).strip(), 'nombre': str(r_cxc['nombre']).strip()}

                    # 3. Facturas Pendientes (Selectbox 1)
                    query_pendientes = """
                        SELECT id, rif_cliente, n_factura, n_control, fecha_emision, base_imponible, monto_iva, monto_bruto, 
                               COALESCE(monto_abonado, 0.00) as monto_abonado, estado_cobro
                        FROM ordenes_cobranza
                        WHERE (estado_cobro NOT IN ('Conciliado', 'PAGADO', 'Pagado', 'Procesado') OR estado_cobro IS NULL OR estado_cobro = 'PENDIENTE')
                        ORDER BY fecha_emision DESC
                    """
                    df_cob_pend = ejecutar_consulta(query_pendientes, conn_c)

                    # 4. Facturas ya Cobradas / Conciliadas (Selectbox 2)
                    query_conciliadas = """
                        SELECT id, rif_cliente, n_factura, n_control, fecha_emision, monto_bruto, 
                               COALESCE(monto_abonado, monto_bruto) as monto_abonado, referencia_banco, banco_receptor, estado_cobro, fecha_cobranza
                        FROM ordenes_cobranza
                        WHERE estado_cobro IN ('Conciliado', 'PAGADO', 'Pagado', 'Procesado')
                        ORDER BY fecha_cobranza DESC
                    """
                    df_cob_conciliadas = ejecutar_consulta(query_conciliadas, conn_c)

            except Exception:
                pass
            finally:
                try:
                    if conn_c and hasattr(conn_c, 'close'):
                        conn_c.close()
                except Exception:
                    pass
            return b_lista, b_dict, cxc_lista, cxc_dict, df_cob_pend, df_cob_conciliadas

        lista_bancos_detalle, dict_bancos_detalle, lista_cxc_detalle, dict_cxc_detalle, df_pendientes, df_conciliadas = cargar_datos_cobranza_opt(db_actual)

        # Helper para renderizar la tabla HTML del Asiento
        def render_asiento_html(n_comp, desc, fecha_str, cta_d_code, cta_d_nom, cta_h_code, cta_h_nom, ref, monto):
            return f"""
            <style>
                .tabla-asiento {{ width: 100%; border-collapse: collapse; font-family: sans-serif; font-size: 13px; margin: 10px 0; background-color: #ffffff; box-shadow: 0 2px 5px rgba(0,0,0,0.1); border-radius: 6px; overflow: hidden; }}
                .tabla-asiento th {{ background-color: #f8f9fa; color: #333; padding: 10px; text-align: left; border-bottom: 2px solid #dee2e6; font-weight: bold; }}
                .tabla-asiento td {{ padding: 9px 10px; border-bottom: 1px solid #e9ecef; color: #212529; }}
                .monto-col {{ text-align: right; font-family: monospace; font-weight: bold; }}
            </style>
            <table class="tabla-asiento">
                <thead>
                    <tr><th>N° Comprobante</th><th>Descripción</th><th>Fecha</th><th>Plan Cuentas</th><th>Cuenta Contable</th><th>Referencia</th><th style="text-align: right;">Debe</th><th style="text-align: right;">Haber</th></tr>
                </thead>
                <tbody>
                    <tr><td><b>{n_comp}</b></td><td>{desc}</td><td>{fecha_str}</td><td><code>{cta_d_code}</code></td><td>{cta_d_nom}</td><td>{ref}</td><td class="monto-col" style="color: #2b8a3e;">{monto:,.2f}</td><td class="monto-col">0.00</td></tr>
                    <tr><td><b>{n_comp}</b></td><td>{desc}</td><td>{fecha_str}</td><td><code>{cta_h_code}</code></td><td>{cta_h_nom}</td><td>{ref}</td><td class="monto-col">0.00</td><td class="monto-col" style="color: #c92a2a;">{monto:,.2f}</td></tr>
                </tbody>
                <tfoot>
                    <tr style="background-color: #f8f9fa; font-weight: bold;"><td colspan="6" style="text-align: right;">TOTALES:</td><td class="monto-col" style="color: #2b8a3e;">{monto:,.2f}</td><td class="monto-col" style="color: #c92a2a;">{monto:,.2f}</td></tr>
                </tfoot>
            </table>
            """

        # =========================================================================
        # ⚡ SELECTBOX 1: FACTURAS PENDIENTES / POR COBRAR (Nuevos Abonos o Pagos)
        # =========================================================================
        st.markdown("### 1️⃣ Facturas Pendientes por Cobrar")
        if df_pendientes is not None and not df_pendientes.empty:
            df_pendientes['monto_bruto'] = pd.to_numeric(df_pendientes['monto_bruto'], errors='coerce').fillna(0.0)
            df_pendientes['monto_abonado'] = pd.to_numeric(df_pendientes['monto_abonado'], errors='coerce').fillna(0.0)
            df_pendientes['saldo_pendiente'] = df_pendientes['monto_bruto'] - df_pendientes['monto_abonado']
            
            dict_cobs_pend = {
                f"ID: {row['id']} | Factura: {row['n_factura']} | RIF: {row['rif_cliente']} | Total: {row['monto_bruto']:,.2f} | Restante: {row['saldo_pendiente']:,.2f}": row['id']
                for _, row in df_pendientes.iterrows()
            }
            
            selected_cob_label = st.selectbox("Selecciona la Orden de Cobranza / Factura a Cobrar", list(dict_cobs_pend.keys()), key="select_cob_cruce_pend")
            fila_cob_sel = df_pendientes[df_pendientes['id'] == dict_cobs_pend[selected_cob_label]].iloc[0]
            
            monto_total_fact = float(fila_cob_sel['monto_bruto'])
            monto_ya_abonado = float(fila_cob_sel['monto_abonado'])
            saldo_restante = float(fila_cob_sel['saldo_pendiente'])

            st.info(f"💡 **Información:** Total Factura: `{monto_total_fact:,.2f}` | Abonado: `{monto_ya_abonado:,.2f}` | **Saldo Pendiente: `{saldo_restante:,.2f}`**")

            col_m1, col_m2, col_m3 = st.columns(3)
            with col_m1:
                referencia_bancaria = st.text_input("Número de Referencia Bancaria", key="input_ref_banco_cob").strip()
            with col_m2:
                fecha_cobro_real = st.date_input("Fecha de Cobro (Banco)", value=date.today(), key="input_fec_banco_cob")
            with col_m3:
                max_abono = max(0.01, saldo_restante)
                val_abono = min(max_abono, max(0.01, saldo_restante))
                monto_abono = st.number_input(
                    "Monto de este Abono / Cuota",
                    min_value=0.01,
                    max_value=max_abono,
                    value=val_abono,
                    step=10.0,
                    format="%.2f",
                    key=f"input_monto_abono_{int(fila_cob_sel['id'])}"
                )

            col_cta1, col_cta2 = st.columns(2)
            with col_cta1:
                cta_banco_entrada = st.selectbox("🏦 Cuenta Bancaria / Entrada (Debe)", options=lista_bancos_detalle if lista_bancos_detalle else ["N/A"], key="select_banco_entrada_cobro")
            with col_cta2:
                cta_cxc_salida = st.selectbox("📋 Cuenta por Cobrar / Cliente (Haber)", options=lista_cxc_detalle if lista_cxc_detalle else ["N/A"], key="select_cxc_salida_cobro")

            info_banco_prev = dict_bancos_detalle.get(cta_banco_entrada, {'codigo': '1.1.2.01.001', 'nombre': 'Banco Principal'})
            info_cxc_prev = dict_cxc_detalle.get(cta_cxc_salida, {'codigo': '1.1.3.01.001', 'nombre': 'Cuentas por Cobrar Comerciales'})

            n_fact_prev = str(fila_cob_sel['n_factura'])
            rif_prev = str(fila_cob_sel['rif_cliente'])
            n_comp_prev = f"COB-{n_fact_prev}"
            desc_prev = f"Abono Factura N° {n_fact_prev} - Cliente RIF: {rif_prev}"
            ref_prev = referencia_bancaria if referencia_bancaria else "(Sin Ref)"

            st.markdown("#### 📊 Previsualización del Asiento Contable")
            st.markdown(render_asiento_html(n_comp_prev, desc_prev, str(fecha_cobro_real), info_banco_prev['codigo'], info_banco_prev['nombre'], info_cxc_prev['codigo'], info_cxc_prev['nombre'], ref_prev, monto_abono), unsafe_allow_html=True)

            if st.button("💾 Registrar Abono, Banco y Generar Asiento", type="primary", key="btn_guardar_cobro_completo", use_container_width=True):
                if not referencia_bancaria:
                    st.warning("⚠️ Ingresa la referencia bancaria obligatoriamente.")
                elif not lista_bancos_detalle or "N/A" in cta_banco_entrada:
                    st.error("⚠️ Selecciona una cuenta bancaria válida.")
                else:
                    conn_tx = None
                    try:
                        conn_tx = conectar_db(db_actual)
                        if conn_tx:
                            with conn_tx.cursor() as cursor_tx:
                                nuevo_abonado_total = monto_ya_abonado + monto_abono
                                nuevo_estado = 'Conciliado' if nuevo_abonado_total >= monto_total_fact else 'PENDIENTE'

                                query_asiento = "INSERT INTO asientos_contables (n_comprobante, descripcion, fecha, plan_cuentas, cuenta_contable, referencia, debe, haber, bloqueado) VALUES (%s, %s, %s, %s, %s, %s, %s, %s, 0)"
                                
                                # Debe (Banco)
                                cursor_tx.execute(query_asiento, (n_comp_prev, desc_prev, str(fecha_cobro_real), info_banco_prev['codigo'], info_banco_prev['nombre'], referencia_bancaria, monto_abono, 0.00))
                                asiento_id_gen = cursor_tx.lastrowid

                                # Haber (CxC)
                                cursor_tx.execute(query_asiento, (n_comp_prev, desc_prev, str(fecha_cobro_real), info_cxc_prev['codigo'], info_cxc_prev['nombre'], referencia_bancaria, 0.00, monto_abono))

                                # Movimiento Bancario
                                cursor_tx.execute("INSERT INTO banco_movimientos (banco_nombre, cuenta_numero, fecha_movimiento, referencia, descripcion, monto, banco_receptor, estado_conciliacion, asiento_id) VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s)",
                                                  (info_banco_prev['nombre'], info_banco_prev['codigo'], str(fecha_cobro_real), referencia_bancaria, desc_prev, monto_abono, info_banco_prev['nombre'], 'Conciliado', asiento_id_gen))

                                # Actualizar Orden
                                cursor_tx.execute("UPDATE ordenes_cobranza SET monto_abonado = %s, referencia_banco = %s, banco_receptor = %s, fecha_cobranza = %s, estado_cobro = %s WHERE id = %s",
                                                  (nuevo_abonado_total, referencia_bancaria, info_banco_prev['nombre'], fecha_cobro_real, nuevo_estado, int(fila_cob_sel['id'])))

                                conn_tx.commit()

                            cargar_datos_cobranza_opt.clear()
                            st.success(f"✅ ¡Abono registrado con éxito! La factura se ha actualizado.")
                            st.rerun()
                    except Exception as ex_m:
                        st.error(f"❌ Error al procesar el abono: {ex_m}")
                    finally:
                        try:
                            if conn_tx and hasattr(conn_tx, 'close'): conn_tx.close()
                        except Exception: pass
        else:
            st.info("🎉 No hay órdenes de cobranza pendientes por cobrar en este momento.")

        st.divider()

        # =========================================================================
        # ⚡ SELECTBOX 2: FACTURAS YA COBRADAS / CONCILIADAS (Gestión y Reversión)
        # =========================================================================
        st.markdown("### 2️⃣ Facturas Ya Cobradas / Conciliadas (Gestión y Reversión)")
        if df_conciliadas is not None and not df_conciliadas.empty:
            dict_conciliadas = {
                f"ID: {r['id']} | Factura: {r['n_factura']} | RIF: {r['rif_cliente']} | Total: {r['monto_bruto']:,.2f} | Ref: {r['referencia_banco']}": r 
                for _, r in df_conciliadas.iterrows()
            }
            
            selected_conc_label = st.selectbox("Selecciona la factura cobrada a gestionar o revertir", list(dict_conciliadas.keys()), key="select_gestion_cob_conc")
            
            if selected_conc_label:
                row_conc = dict_conciliadas[selected_conc_label]
                n_fact_h = str(row_conc['n_factura'])
                n_comp_h = f"COB-{n_fact_h}"

                st.markdown(f"📄 **Detalles del Cobro:** Banco: `{row_conc['banco_receptor']}` | Ref: `{row_conc['referencia_banco']}` | Fecha Banco: `{row_conc['fecha_cobranza']}`")

                if st.button("🔄 Revertir Cobro y Anular Asiento Contable", type="secondary", key=f"btn_revert_cob_{row_conc['id']}", use_container_width=True):
                    conn_rev = None
                    try:
                        conn_rev = conectar_db(db_actual)
                        if conn_rev:
                            with conn_rev.cursor() as cur_r:
                                # 1. Eliminar asientos contables asociados
                                cur_r.execute("DELETE FROM asientos_contables WHERE n_comprobante = %s", (n_comp_h,))
                                
                                # 2. Eliminar movimientos bancarios asociados
                                cur_r.execute("DELETE FROM banco_movimientos WHERE referencia = %s OR asiento_id IN (SELECT id FROM asientos_contables WHERE n_comprobante = %s)", (str(row_conc['referencia_banco']), n_comp_h))
                                
                                # 3. Devolver orden a estado PENDIENTE y reiniciar abonos
                                cur_r.execute("UPDATE ordenes_cobranza SET estado_cobro = 'PENDIENTE', monto_abonado = 0.00, referencia_banco = NULL, banco_receptor = NULL, fecha_cobranza = NULL WHERE id = %s", (int(row_conc['id']),))
                                
                                conn_rev.commit()

                            cargar_datos_cobranza_opt.clear()
                            st.warning(f"⚠️ El cobro de la factura **{n_fact_h}** ha sido revertido con éxito. La factura regresó al **Selectbox 1 (Pendientes)**.")
                            st.rerun()
                    except Exception as err_rev:
                        st.error(f"❌ Error al revertir: {err_rev}")
                    finally:
                        try:
                            if conn_rev and hasattr(conn_rev, 'close'): conn_rev.close()
                        except Exception: pass
        else:
            st.info("ℹ️ No hay facturas cobradas/conciliadas disponibles para revertir.")

    except Exception as e:
        st.error(f"Error en el módulo de cobranzas: {e}")
    finally:
        try:
            if 'conn' in locals() and conn: conn.close()
        except Exception: pass

def generar_pdf_resumen_seniat(records, empresa_nombre, periodo_str, tot_base, tot_sust, tot_neta):
    pdf = FPDF(orientation='L', unit='mm', format='A4') # Orientación Horizontal
    pdf.set_auto_page_break(auto=True, margin=15)
    pdf.add_page()
    
    # Encabezado
    pdf.set_font("Helvetica", "B", 14)
    pdf.cell(0, 8, f"RESUMEN DE RETENCIONES DE ISLR PARA EL SENIAT", ln=True, align="C")
    pdf.set_font("Helvetica", "", 10)
    pdf.cell(0, 6, f"Empresa / Cliente: {empresa_nombre}  |  Periodo Fiscal: {periodo_str}", ln=True, align="C")
    pdf.ln(5)
    
    # Encabezados de la Tabla (Ancho total A4 Landscape ~ 277mm)
    pdf.set_font("Helvetica", "B", 8)
    pdf.set_fill_color(240, 240, 240)
    
    ancho_cols = {
        'Fila / Doc': 25, 'Fecha': 20, 'N° Doc': 20, 'N° Control': 22, 
        'R.I.F.': 25, 'Nombre o Razón Social': 60, 'Cód. Concepto (XML)': 25, 
        'Base Imponible (Bs.)': 28, 'Sustraendo (Bs.)': 25, 'Retención Neta (Bs.)': 27
    }
    
    for col, width in ancho_cols.items():
        pdf.cell(width, 7, col[:15], border=1, align="C", fill=True)
    pdf.ln()
    
    # Contenido de Filas
    pdf.set_font("Helvetica", "", 8)
    for row in records:
        pdf.cell(ancho_cols['Fila / Doc'], 6, str(row.get('Fila / Doc', ''))[:14], border=1)
        pdf.cell(ancho_cols['Fecha'], 6, str(row.get('Fecha', '')), border=1, align="C")
        pdf.cell(ancho_cols['N° Doc'], 6, str(row.get('N° Doc', '')), border=1, align="C")
        pdf.cell(ancho_cols['N° Control'], 6, str(row.get('N° Control', '')), border=1, align="C")
        pdf.cell(ancho_cols['R.I.F.'], 6, str(row.get('R.I.F.', '')), border=1, align="C")
        pdf.cell(ancho_cols['Nombre o Razón Social'], 6, str(row.get('Nombre o Razón Social', ''))[:32], border=1)
        pdf.cell(ancho_cols['Cód. Concepto (XML)'], 6, str(row.get('Cód. Concepto (XML)', '')), border=1, align="C")
        
        base_val = float(row.get('Base Imponible (Bs.)', 0) or 0)
        sust_val = float(row.get('Sustraendo (Bs.)', 0) or 0)
        neto_val = float(row.get('Retención Neta (Bs.)', 0) or 0)
        
        pdf.cell(ancho_cols['Base Imponible (Bs.)'], 6, f"{base_val:,.2f}", border=1, align="R")
        pdf.cell(ancho_cols['Sustraendo (Bs.)'], 6, f"{sust_val:,.2f}", border=1, align="R")
        pdf.cell(ancho_cols['Retención Neta (Bs.)'], 6, f"{neto_val:,.2f}", border=1, align="R")
        pdf.ln()
        
    # Fila de Totales
    pdf.set_font("Helvetica", "B", 8)
    pdf.set_fill_color(230, 230, 230)
    ancho_acumulado_texto = sum([ancho_cols['Fila / Doc'], ancho_cols['Fecha'], ancho_cols['N° Doc'], ancho_cols['N° Control'], ancho_cols['R.I.F.'], ancho_cols['Nombre o Razón Social'], ancho_cols['Cód. Concepto (XML)']])
    
    pdf.cell(ancho_acumulado_texto, 7, "TOTALES GENERALES A ENTERAR AL SENIAT:", border=1, align="R", fill=True)
    pdf.cell(ancho_cols['Base Imponible (Bs.)'], 7, f"{tot_base:,.2f}", border=1, align="R", fill=True)
    pdf.cell(ancho_cols['Sustraendo (Bs.)'], 7, f"{tot_sust:,.2f}", border=1, align="R", fill=True)
    pdf.cell(ancho_cols['Retención Neta (Bs.)'], 7, f"{tot_neta:,.2f}", border=1, align="R", fill=True)
    
    return bytes(pdf.output())


@st.cache_data(ttl=300)
def _obtener_empresas_sidebar_cache(user_rol, user_limpio):
    conn_sidebar = conectar_db()
    if conn_sidebar is None:
        return []

    df_sidebar = pd.DataFrame()
    try:
        if hasattr(conn_sidebar, 'ping') and callable(conn_sidebar.ping):
            conn_sidebar.ping(reconnect=True)
        
        cursor_tmp = conn_sidebar.cursor()
        try:
            cursor_tmp.execute("USE control_central;")
        except Exception:
            pass 
        cursor_tmp.close()

        if user_rol == 'admin':
            queries_a_probar = [
                "SELECT * FROM control_central.clientes",
                "SELECT * FROM clientes"
            ]
        else:
            queries_a_probar = [
                f"""
                SELECT c.* FROM control_central.clientes c
                JOIN control_central.usuarios u ON c.id = u.cliente_id
                WHERE LOWER(TRIM(u.usuario)) = '{user_limpio}'
                """,
                f"""
                SELECT * FROM control_central.clientes WHERE id = 3
                """
            ]
    
        for q in queries_a_probar:
            try:
                df_temp = ejecutar_consulta(q, conn_sidebar)
                if not df_temp.empty:
                    df_sidebar = df_temp
                    break
            except Exception:
                continue
    except Exception:
        pass
    finally:
        try:
            if conn_sidebar and hasattr(conn_sidebar, 'close'):
                conn_sidebar.close()
        except:
            pass

    # --- RESPALDO OBLIGATORIO PARA ALIX ---
    if df_sidebar.empty and user_limpio == 'alix_maria':
        df_sidebar = pd.DataFrame([{
            'id': 3,
            'nombre_empresa': 'Distribuidora Rishon Leztion, C.A.',
            'rif': 'J-XXXXXXXX-X',
            'db_nombre': 'rishon_letzion_ca'
        }])

    # --- RESPALDO OBLIGATORIO PARA ELENITA ---
    elif df_sidebar.empty and user_limpio == 'elenita':
        df_sidebar = pd.DataFrame([{
            'id': 1,  # Ajusta el ID según corresponda
            'nombre_empresa': 'King Driver, C.A.',  # Ajusta el nombre de la empresa
            'rif': 'J-XXXXXXXX-X',
            'db_nombre': 'kingdirver_ca'  # Ajusta el nombre de la base de datos real
        }])

    if not df_sidebar.empty:
        df_sidebar = df_sidebar.fillna("")

    return df_sidebar.to_dict('records')




def generar_pdf_preimpreso(conn, datos_factura, items_factura):
    """
    Genera un PDF transparente con los datos posicionados milimétricamente
    según las columnas de coordenadas de la tabla config_factura_preimpresa en MySQL.
    """
    cursor = conn.cursor(dictionary=True)
    
    # Consultamos la fila de configuración de la tabla
    cursor.execute("SELECT * FROM config_factura_preimpresa LIMIT 1")
    config = cursor.fetchone() or {}
    cursor.close()

    buffer = io.BytesIO()
    c = canvas.Canvas(buffer, pagesize=letter)
    
    fuente_base = int(config.get('fuente_tamanio', 10) or 10)

    def dibujar(x_col, y_col, texto, bold=False, tam=None):
        if config.get(x_col) is not None and config.get(y_col) is not None:
            x = float(config[x_col]) * mm
            # Conversión de milímetros desde arriba hacia el sistema de coordenadas de ReportLab (desde abajo)
            y = (279.4 - float(config[y_col])) * mm
            tamanio = tam if tam else fuente_base
            font = "Helvetica-Bold" if bold else "Helvetica"
            c.setFont(font, tamanio)
            c.drawString(x, y, str(texto or ''))

    # --- Cabecera / Documento ---
    dibujar('nro_factura_x', 'nro_factura_y', datos_factura.get('nro_factura', ''), bold=True, tam=11)
    dibujar('nro_control_x', 'nro_control_y', datos_factura.get('nro_control', ''), bold=True, tam=11)
    dibujar('fecha_x', 'fecha_y', datos_factura.get('fecha_emision', ''))

    # --- Datos del Cliente ---
    dibujar('cliente_nombre_x', 'cliente_nombre_y', datos_factura.get('razon_social', ''))
    dibujar('cliente_rif_x', 'cliente_rif_y', datos_factura.get('rif_cliente', ''))
    
    # Dirección fiscal del cliente mapeada con cliente_direccion_x / cliente_direccion_y
    dir_cliente = datos_factura.get('direccion_fiscal', datos_factura.get('direccion_cliente', ''))
    dibujar('cliente_direccion_x', 'cliente_direccion_y', dir_cliente[:70])

    # --- Totales y Montos Fiscales al Pie ---
    dibujar('exento_x', 'exento_y', datos_factura.get('monto_exento', '0.00'))
    dibujar('base_imponible_x', 'base_imponible_y', datos_factura.get('base_imponible', '0.00'))
    dibujar('iva_x', 'iva_y', datos_factura.get('monto_iva', '0.00'))
    dibujar('monto_total_x', 'monto_total_y', datos_factura.get('monto_total', '0.00'), bold=True, tam=11)

    c.save()
    buffer.seek(0)
    return buffer.getvalue()


from fpdf import FPDF
import io

class PDFReporteAuxiliar(FPDF):
    def __init__(self, empresa_nombre, proveedor_nombre, f_desde, f_hasta, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.empresa_nombre = str(empresa_nombre).encode('latin-1', 'replace').decode('latin-1')
        self.proveedor_nombre = str(proveedor_nombre).encode('latin-1', 'replace').decode('latin-1')
        self.f_desde = str(f_desde)
        self.f_hasta = str(f_hasta)

    def header(self):
        self.set_font('helvetica', 'B', 14)
        self.cell(0, 8, "ESTADO DE CUENTA / AUXILIAR CXP", 0, 1, 'C')
        self.set_font('helvetica', 'B', 10)
        self.cell(0, 6, f"Empresa: {self.empresa_nombre}", 0, 1, 'C')
        self.cell(0, 6, f"Proveedor: {self.proveedor_nombre}", 0, 1, 'C')
        self.cell(0, 6, f"Periodo: {self.f_desde} al {self.f_hasta}", 0, 1, 'C')
        self.ln(5)

        self.set_font('helvetica', 'B', 8)
        self.set_fill_color(240, 242, 246)
        
        self.cell(20, 6, "Fecha", 1, 0, 'C', True)
        self.cell(22, 6, "Comprobante", 1, 0, 'C', True)
        self.cell(18, 6, "Plan Ctas", 1, 0, 'C', True)
        self.cell(50, 6, "Descripcion", 1, 0, 'C', True)
        self.cell(22, 6, "Debe", 1, 0, 'R', True)
        self.cell(22, 6, "Haber", 1, 0, 'R', True)
        self.cell(26, 6, "Saldo", 1, 1, 'R', True)

    def footer(self):
        self.set_y(-15)
        self.set_font('helvetica', 'I', 8)
        self.cell(0, 10, f"Pagina {self.page_no()} / {{nb}}", 0, 0, 'C')


def generar_pdf_auxiliar_cxp(df_vista, proveedor_nombre, empresa_nombre, f_desde, f_hasta):
    try:
        pdf = PDFReporteAuxiliar(empresa_nombre, proveedor_nombre, str(f_desde), str(f_hasta), orientation='P', unit='mm', format='A4')
        pdf.alias_nb_pages()
        pdf.add_page()
        pdf.set_font('helvetica', '', 8)

        for _, row in df_vista.iterrows():
            fecha = str(row.get('Fecha', ''))
            comp = str(row.get('Comprobante', ''))
            plan = str(row.get('Plan Cuentas', ''))
            
            # Sanitizar texto para evitar crash de codificación latin-1 en Helvetica
            desc_raw = str(row.get('Descripción', row.get('Descripcion', '')))
            desc = desc_raw.encode('latin-1', 'replace').decode('latin-1')
            if len(desc) > 30:
                desc = desc[:27] + "..."
            
            debe = float(row.get('Debe', 0.0))
            haber = float(row.get('Haber', 0.0))
            saldo = float(row.get('Saldo', 0.0))

            pdf.cell(20, 6, fecha, 1, 0, 'C')
            pdf.cell(22, 6, comp, 1, 0, 'C')
            pdf.cell(18, 6, plan, 1, 0, 'C')
            pdf.cell(50, 6, desc, 1, 0, 'L')
            pdf.cell(22, 6, f"{debe:,.2f}", 1, 0, 'R')
            pdf.cell(22, 6, f"{haber:,.2f}", 1, 0, 'R')
            pdf.cell(26, 6, f"{saldo:,.2f}", 1, 1, 'R')

        # Garantizar que devuelva bytes compatibles con Streamlit
        res_output = pdf.output()
        if isinstance(res_output, str):
            return res_output.encode('latin-1')
        return bytes(res_output)
    except Exception as e:
        print(f"Error generando PDF: {e}")
        return b""
# ==============================================================================
# 1. FUNCIÓN BACKEND: GENERAR AUXILIAR DE CUENTAS POR PAGAR
# ==============================================================================
def generar_auxiliar_cxp(conn, fecha_desde, fecha_hasta, proveedor_seleccionado=None):
    """
    Genera un DataFrame con el Auxiliar de Cuentas por Pagar detallado por comprobante,
    filtrando estrictamente para que solo involucre comprobantes y transacciones de 
    la cuenta de Proveedores Nacionales (2.1.1.01.001).
    """
    try:
        f_hasta_str = fecha_hasta.strftime('%Y-%m-%d') if hasattr(fecha_hasta, 'strftime') else str(fecha_hasta)
        f_desde_str = fecha_desde.strftime('%Y-%m-%d') if hasattr(fecha_desde, 'strftime') else str(fecha_desde)

        # 💡 CONSULTA ESTRICTA: Solo traemos comprobantes que contengan la cuenta 2.1.1.01.001
        query = """
            SELECT id, n_comprobante, fecha, descripcion, plan_cuentas, cuenta_contable, referencia, debe, haber
            FROM asientos_contables
            WHERE n_comprobante IN (
                SELECT DISTINCT n_comprobante 
                FROM asientos_contables 
                WHERE plan_cuentas = '2.1.1.01.001' 
                  AND fecha <= %s
            )
            ORDER BY fecha ASC, n_comprobante ASC, id ASC
        """
        df_total = ejecutar_consulta(query, conn, params=(f_hasta_str,))
        
        if df_total is None or df_total.empty:
            return pd.DataFrame()

        df_total['debe'] = pd.to_numeric(df_total['debe'], errors='coerce').fillna(0.0)
        df_total['haber'] = pd.to_numeric(df_total['haber'], errors='coerce').fillna(0.0)
        
        df_total['fecha_dt'] = pd.to_datetime(df_total['fecha'])
        df_total['fecha'] = df_total['fecha_dt'].dt.strftime('%Y-%m-%d')

        # Extracción estricta de proveedores evitando textos de bancos o pagos
        def extraer_proveedor_base(desc):
            if not isinstance(desc, str):
                return ""
            
            d_upper = desc.upper().strip()
            
            # Palabras prohibidas que descartan completamente la línea como nombre de proveedor
            palabras_excluidas = [
                "PAGO A", "PAGOS", "BANCO", "TRANSFERENCIA", "NOTA DE", 
                "AJUSTES", "IVSS", "SENIAT", "BANCRECER", "BDV", "LOTE"
            ]
            if any(p in d_upper for p in palabras_excluidas):
                return ""

            # Si tiene estructura con guion (ej: FACTURA 1 - NOMBRE PROVEEDOR)
            if "-" in desc:
                partes = desc.split("-")
                candidato = partes[-1].strip()
                c_up = candidato.upper()
                if len(candidato) > 3 and not any(p in c_up for p in palabras_excluidas):
                    return candidato
            
            # Si el texto de la descripción misma es un nombre válido de entidad
            if len(desc.strip()) > 3:
                return desc.strip()
                
            return ""

        # Buscamos el proveedor preferiblemente de las filas donde plan_cuentas sea '2.1.1.01.001'
        df_total['es_cuenta_prov'] = df_total['plan_cuentas'].astype(str).str.strip() == '2.1.1.01.001'
        df_total['proveedor_raw'] = df_total['descripcion'].apply(extraer_proveedor_base)

        # Propagar el nombre del proveedor dentro del mismo comprobante dándole prioridad a la línea de la cuenta 2.1.1.01.001
        def obtener_proveedor_comprobante(sub_df):
            provs_filtrados = sub_df[sub_df['es_cuenta_prov']]['proveedor_raw'].tolist()
            for p in provs_filtrados:
                if p and p != "GENERAL / OTROS":
                    return p
            provs_general = sub_df['proveedor_raw'].tolist()
            for p in provs_general:
                if p and p != "GENERAL / OTROS":
                    return p
            return "GENERAL / OTROS"

        # Mapear el proveedor consolidado por comprobante
        mapa_proveedores = df_total.groupby('n_comprobante').apply(obtener_proveedor_comprobante).to_dict()
        df_total['proveedor'] = df_total['n_comprobante'].map(mapa_proveedores).fillna("GENERAL / OTROS")

        if proveedor_seleccionado and proveedor_seleccionado != "TODOS":
            df_total = df_total[df_total['proveedor'] == proveedor_seleccionado]
            if df_total.empty:
                return pd.DataFrame()

        df_periodo = df_total[df_total['fecha_dt'] >= pd.to_datetime(f_desde_str)].copy()

        if df_periodo.empty:
            return pd.DataFrame()

        df_periodo['es_cxp'] = df_periodo['plan_cuentas'].astype(str).str.strip() == '2.1.1.01.001'
        df_periodo['movimiento'] = 0.0
        df_periodo.loc[df_periodo['es_cxp'], 'movimiento'] = df_periodo.loc[df_periodo['es_cxp'], 'haber'] - df_periodo.loc[df_periodo['es_cxp'], 'debe']
        
        df_periodo['saldo_acumulado'] = df_periodo.groupby('proveedor')['movimiento'].cumsum()

        auxiliar_final = df_periodo[[
            'fecha', 'n_comprobante', 'plan_cuentas', 'cuenta_contable', 'referencia', 'descripcion', 
            'proveedor', 'debe', 'haber', 'saldo_acumulado'
        ]].rename(columns={
            'fecha': 'Fecha',
            'n_comprobante': 'Comprobante',
            'plan_cuentas': 'Plan Cuentas',
            'cuenta_contable': 'Cuenta Contable',
            'referencia': 'Referencia / Factura',
            'descripcion': 'Descripción',
            'proveedor': 'Proveedor',
            'debe': 'Debe',
            'haber': 'Haber',
            'saldo_acumulado': 'Saldo'
        })

        return auxiliar_final

    except Exception as e:
        print(f"Error generando auxiliar de CxP: {e}")
        return pd.DataFrame()


def limpiar_moneda(valor):
    """
    Limpia cadenas de texto con formato de moneda (ej: '1.250,50' o 'Bs. 500') 
    y los convierte en un float flotante estándar para MySQL.
    """
    if valor is None:
        return 0.0
    if isinstance(valor, (int, float)):
        return float(valor)
    
    val_str = str(valor).strip()
    if not val_str or val_str.lower() in ['nan', 'none', 'n/a']:
        return 0.0

    try:
        # Si usa formato europeo/venezolano (puntos para miles, comas para decimales)
        if ',' in val_str and '.' in val_str:
            if val_str.find('.') < val_str.find(','):
                val_str = val_str.replace('.', '').replace(',', '.')
            else:
                val_str = val_str.replace(',', '')
        elif ',' in val_str:
            val_str = val_str.replace(',', '.')
        
        # Remover cualquier carácter que no sea número, signo menos o punto decimal
        val_str = re.sub(r'[^0-9.-]', '', val_str)
        return float(val_str)
    except Exception:
        return 0.0


import pdfplumber  # Asegúrate de importar esto arriba si no lo tienes
# ...

def modulo_escaneo_facturas_qr(conn, db_actual):
    st.subheader("📸 Registro Fiscal de Facturas y Generación QR")
    st.markdown("Sube la factura en formato **PDF** o imagen. El sistema extraerá los datos fiscales automáticamente.")

    # 1. Selector de archivos actualizado para aceptar PDF e imágenes
    archivo_subido = st.file_uploader(
        "Seleccionar o arrastrar la factura (PDF o Imagen)", 
        type=["png", "jpg", "jpeg", "pdf"],
        help="Sube la factura digital en PDF o foto."
    )

    # Variables predeterminadas
    val_factura = ""
    val_control = ""
    val_rif = ""
    val_nombre = ""
    val_domicilio = ""
    val_fecha = date.today()
    val_base = 0.00
    val_iva = 0.00
    val_exento = 0.00
    texto_ocr = ""
    img = None

    if archivo_subido is not None:
        try:
            # Verificamos si es un PDF
            if archivo_subido.type == "application/pdf" or archivo_subido.name.endswith('.pdf'):
                with pdfplumber.open(archivo_subido) as pdf:
                    texto_ocr = ""
                    for pagina in pdf.pages:
                        extracted = pagina.extract_text()
                        if extracted:
                            texto_ocr += extracted + "\n"
                    
                    # Si el PDF tiene texto digital directo, lo convertimos también a imagen para mostrarlo en pantalla
                    primer_pag = pdf.pages[0]
                    img_pil = primer_pag.to_image(resolution=150)
                    img = img_pil.original
            else:
                img = Image.open(archivo_subido)
                texto_ocr = pytesseract.image_to_string(img)

            lineas = [l.strip() for l in texto_ocr.split('\n') if l.strip()]

            # A. Nombre del Proveedor (Ej: BUFITO, C.A)
            for l in lineas[:6]:
                l_upper = l.upper()
                if not any(k in l_upper for k in ["RIF", "FACTURA", "AV", "CALLE", "ZONA", "CORREO"]) and len(l) > 3:
                    val_nombre = l
                    break
            if not val_nombre and len(lineas) > 0:
                val_nombre = lineas[0]

            # B. Domicilio Fiscal
            domicilio_lines = []
            for l in lineas:
                l_upper = l.upper()
                if any(k in l_upper for k in ["AV ", "CALLE ", "SECTOR ", "URB ", "CARACAS", "APURE"]):
                    domicilio_lines.append(l)
            if domicilio_lines:
                val_domicilio = ", ".join(domicilio_lines[:2])

            # C. RIF del Proveedor (Ej: J-317227719)
            match_rif = re.search(r'RIF[:]?\s*([VJGED]\s*[-]?\s*\d{7,9}\s*[-]?\s*\d)', texto_ocr, re.IGNORECASE)
            if match_rif:
                val_rif = re.sub(r'\s+', '', match_rif.group(1)).upper()

            # D. Número de Factura (Ej: 00006753)
            match_factura = re.search(r'(?:N°\s*Documento|Factura).*?([0-9]{4,8})', texto_ocr, re.IGNORECASE)
            if match_factura:
                val_factura = match_factura.group(1)

            # E. Número de Control (Ej: 00-024470)
            match_control = re.search(r'Control[:]?\s*([0-9O\-]{5,12})', texto_ocr, re.IGNORECASE)
            if match_control:
                val_control = match_control.group(1).replace('O', '0').replace('o', '0').strip()

            # F. Fecha de Emisión (Ej: 11/05/2026)
            match_fec = re.search(r'Fecha.*?emisi[oó]n[:]?\s*(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{2,4})', texto_ocr, re.IGNORECASE)
            if match_fec:
                try:
                    d, m, y = int(match_fec.group(1)), int(match_fec.group(2)), int(match_fec.group(3))
                    if y < 100: y += 2000
                    val_fecha = date(y, m, d)
                except:
                    pass

            # G. Base Imponible (Ej: 65.710,49 Bs)
            match_base = re.search(r'Base.*?imponible.*?([\d\.,]+)\s*Bs', texto_ocr, re.IGNORECASE)
            if match_base:
                try:
                    val_base = float(match_base.group(1).replace('.', '').replace(',', '.'))
                except:
                    pass

            # H. IVA (Ej: 10.513,68 Bs)
            match_iva = re.search(r'IVA.*?([\d\.,]+)\s*Bs', texto_ocr, re.IGNORECASE)
            if match_iva:
                try:
                    val_iva = float(match_iva.group(1).replace('.', '').replace(',', '.'))
                except:
                    val_iva = round(val_base * 0.16, 2)

            st.success("✅ ¡Factura en PDF procesada con éxito por el sistema digital!")

        except Exception as e:
            st.warning(f"⚠️ Nota de lectura digital: {e}")

        # 💡 DISEÑO EN DOS COLUMNAS
        col_izq, col_der = st.columns([1, 1.2])

        with col_izq:
            if img:
                st.image(img, caption="Vista Previa de la Factura", use_container_width=True)
            st.markdown("#### 🔍 Texto Extraído del PDF")
            st.code(texto_ocr if texto_ocr else "Sin texto detectado", language="text")

        with col_der:
            st.markdown("### 📝 Verificación y Carga Digital")
            with st.form("form_datos_factura_qr"):
                nro_factura = st.text_input("Número de Factura", value=val_factura)
                nro_control = st.text_input("Número de Control", value=val_control)
                rif_prov = st.text_input("RIF del Proveedor", value=val_rif)
                nombre_prov = st.text_input("Nombre del Proveedor", value=val_nombre)
                
                str_fecha_def = val_fecha.strftime('%Y-%m-%d') if isinstance(val_fecha, date) else str(val_fecha)
                fecha_str = st.text_input("Fecha de la Factura (AAAA-MM-DD o DD/MM/AAAA)", value=str_fecha_def)
                
                base_imp_str = st.text_input("Base Imponible Bs.", value=f"{val_base:.2f}" if val_base > 0 else "")
                monto_iva_str = st.text_input("IVA (16%) Bs.", value=f"{val_iva:.2f}" if val_iva > 0 else "")
                monto_ex_str = st.text_input("Monto Exento Bs.", value="0.00")

                domicilio = st.text_area("Domicilio Fiscal", value=val_domicilio)

                try:
                    val_b = float(re.sub(r'[^0-9.]', '', base_imp_str.replace(',', '.'))) if base_imp_str else 0.00
                except:
                    val_b = 0.00
                    
                try:
                    val_i = float(re.sub(r'[^0-9.]', '', monto_iva_str.replace(',', '.'))) if monto_iva_str else round(val_b * 0.16, 2)
                except:
                    val_i = round(val_b * 0.16, 2)

                try:
                    val_e = float(re.sub(r'[^0-9.]', '', monto_ex_str.replace(',', '.'))) if monto_ex_str else 0.00
                except:
                    val_e = 0.00

                monto_total = val_b + val_i + val_e
                st.info(f"💰 **Monto Total Calculado:** {monto_total:,.2f} Bs.")

                submitted = st.form_submit_button("💾 Guardar y Generar Código QR", type="primary")

                if submitted:
                    if not nro_factura or not nombre_prov or not rif_prov or not fecha_str:
                        st.error("⚠️ Complete los campos obligatorios (Factura, RIF, Proveedor y Fecha).")
                    elif not conn:
                        st.error("⚠️ Sin conexión a la base de datos.")
                    else:
                        try:
                            fecha_str_clean = fecha_str.strip()
                            if "/" in fecha_str_clean:
                                fecha_fac_final = datetime.strptime(fecha_str_clean, '%d/%m/%Y').date()
                            else:
                                fecha_fac_final = datetime.strptime(fecha_str_clean, '%Y-%m-%d').date()

                            with conn.cursor() as cursor:
                                sql = """
                                    INSERT INTO facturas_escaneadas 
                                    (rif_proveedor, nombre_proveedor, domicilio_fiscal, nro_factura, nro_control, fecha_factura, base_imponible, iva, monto_exento, monto_total)
                                    VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
                                """
                                cursor.execute(sql, (
                                    rif_prov, nombre_prov, domicilio, nro_factura, nro_control, 
                                    fecha_fac_final, val_b, val_i, val_e, monto_total
                                ))
                                conn.commit()

                            st.success("¡Factura digital registrada en MySQL correctamente!")

                            info_qr = (
                                f"FACTURA DIGITAL / AUDITORÍA SENIAT\n"
                                f"Factura: {nro_factura} | Control: {nro_control}\n"
                                f"Fecha: {fecha_fac_final.strftime('%d/%m/%Y')}\n"
                                f"Proveedor: {nombre_prov} ({rif_prov})\n"
                                f"Base: {val_b:,.2f} | IVA: {val_i:,.2f} | Total: {monto_total:,.2f}"
                            )

                            qr = qrcode.QRCode(version=1, box_size=10, border=4)
                            qr.add_data(info_qr)
                            qr.make(fit=True)

                            img_qr = qr.make_image(fill_color="black", back_color="white")
                            buffer = BytesIO()
                            img_qr.save(buffer, format="PNG")
                            qr_bytes = buffer.getvalue()

                            st.markdown("### 📱 Código QR Fiscal Generado")
                            st.image(qr_bytes, width=220)

                            st.download_button(
                                label="📥 Descargar QR",
                                data=qr_bytes,
                                file_name=f"QR_Factura_{nro_factura}.png",
                                mime="image/png"
                            )

                        except Exception as e:
                            st.error(f"❌ Error al guardar: {e}")


