import calendar
from datetime import date, datetime

TABLAS_CIERRE_CONFIG = {
    "Asientos Contables": {"tabla": "asientos_contables","col_fecha": "fecha","col_bloqueo": "bloqueado"},
    "Libro de Ventas": {"tabla": "libro_ventas","col_fecha": "fecha_factura","col_bloqueo": "bloqueado"},
    "Libro de Compras": {"tabla": "libro_compras","col_fecha": "fecha_operacion","col_bloqueo": "bloqueado"},
    "Retenciones de IVA": {"tabla": "retenciones_iva","col_fecha": "Fecha_Factura","col_bloqueo": "bloqueado"},
    "Retenciones de ISLR": {"tabla": "retenciones_islr","col_fecha": "fecha_operacion","col_bloqueo": "bloqueado"},
    "Movimientos Bancarios": {"tabla": "banco_movimientos","col_fecha": "fecha_movimiento","col_bloqueo": "bloqueado"},
    "Archivo TXT": {"tabla": "archivo_txt","col_fecha": "FechadeFactura","col_bloqueo": "bloqueado"},
    "Saldos Iniciales": {"tabla": "saldos_iniciales","col_fecha": "fecha","col_bloqueo": "bloqueado"},
}

MESES_ES = {
    "Enero": 1, "Febrero": 2, "Marzo": 3, "Abril": 4,
    "Mayo": 5, "Junio": 6, "Julio": 7, "Agosto": 8,
    "Septiembre": 9, "Octubre": 10, "Noviembre": 11, "Diciembre": 12,
}


def _columna_existe(conn, db_name: str, tabla: str, columna: str) -> bool:
    cur = conn.cursor()
    cur.execute(
        """
        SELECT COUNT(*)
        FROM INFORMATION_SCHEMA.COLUMNS
        WHERE TABLE_SCHEMA = %s AND TABLE_NAME = %s AND COLUMN_NAME = %s
        """,
        (db_name, tabla, columna),
    )
    existe = cur.fetchone()[0] > 0
    cur.close()
    return existe


def _aplicar_bloqueo_rango(
    conn,
    db_name: str,
    tabla: str,
    col_fecha: str,
    col_bloqueo: str,
    fecha_desde: date,
    fecha_hasta: date,
    valor_bloqueo: int,
) -> int:
    if not _columna_existe(conn, db_name, tabla, col_bloqueo):
        raise ValueError(f"La tabla `{db_name}`.`{tabla}` no tiene la columna `{col_bloqueo}`.")
    if not _columna_existe(conn, db_name, tabla, col_fecha):
        raise ValueError(f"La tabla `{db_name}`.`{tabla}` no tiene la columna de fecha `{col_fecha}`.")

    sql = (
        f"UPDATE `{db_name}`.`{tabla}` "
        f"SET `{col_bloqueo}` = %s "
        f"WHERE `{col_fecha}` BETWEEN %s AND %s"
    )
    cur = conn.cursor()
    cur.execute(sql, (int(valor_bloqueo), fecha_desde.strftime("%Y-%m-%d"), fecha_hasta.strftime("%Y-%m-%d")))
    afectados = cur.rowcount
    conn.commit()
    cur.close()
    return afectados


import datetime
import streamlit as st


def calcular_linea_nomina(salario_base, frecuencia="Quincenal", bonos=0.0, porc_deducciones=0.0):
    base = float(salario_base or 0.0)
    devengado_base = (base / 2.0) if frecuencia == "Quincenal" else base
    bono_val = float(bonos or 0.0)
    total_devengado = round(devengado_base + bono_val, 2)
    monto_deducciones = round(total_devengado * (float(porc_deducciones or 0.0) / 100.0), 2)
    neto = round(max(0.0, total_devengado - monto_deducciones), 2)
    return {
        "devengado_base": round(devengado_base, 2),
        "bonos": round(bono_val, 2),
        "total_devengado": total_devengado,
        "deducciones": monto_deducciones,
        "neto": neto,
    }

