    import calendar
    import datetime as dt
    import pandas as pd

    def obtener_deuda_proveedores_cierre_mes(conn, anio_actual, mes_num_actual, cuenta_codigo="2.1.1.01.001"):
        """
        Calcula la deuda acumulada con Proveedores Nacionales (cuenta de pasivo, naturaleza haber)
        al último día del mes seleccionado, sumando saldos_iniciales + asientos_contables.
        """
        ultimo_dia = calendar.monthrange(int(anio_actual), int(mes_num_actual))[1]
        fecha_corte = dt.date(int(anio_actual), int(mes_num_actual), ultimo_dia).strftime("%Y-%m-%d")
        codigo_limpio = str(cuenta_codigo).strip()
        patron_codigo = f"{codigo_limpio}%"
        patron_nombre = "%proveedores nacionales%"

        # 1. Saldos iniciales (sin cortar por fecha salvo que lo necesites)
        df_si = ejecutar_consulta(
            """
            SELECT COALESCE(SUM(haber), 0) AS haber_si,
                   COALESCE(SUM(debe), 0) AS debe_si
            FROM saldos_iniciales
            WHERE TRIM(cuenta_contable) LIKE %s
               OR LOWER(cuenta_contable) LIKE %s
            """,
            conn,
            params=(patron_codigo, patron_nombre)
        )

        # 2. Movimientos en asientos_contables hasta el último día del mes seleccionado
        df_mov = ejecutar_consulta(
            """
            SELECT COALESCE(SUM(haber), 0) AS haber_mov,
                   COALESCE(SUM(debe), 0) AS debe_mov
            FROM asientos_contables
            WHERE (TRIM(cuenta_contable) LIKE %s OR LOWER(cuenta_contable) LIKE %s)
              AND fecha <= %s
            """,
            conn,
            params=(patron_codigo, patron_nombre, fecha_corte)
        )

        haber_si = float(pd.to_numeric(df_si.iloc[0]["haber_si"], errors="coerce") or 0.0) if (df_si is not None and not df_si.empty) else 0.0
        debe_si = float(pd.to_numeric(df_si.iloc[0]["debe_si"], errors="coerce") or 0.0) if (df_si is not None and not df_si.empty) else 0.0

        haber_mov = float(pd.to_numeric(df_mov.iloc[0]["haber_mov"], errors="coerce") or 0.0) if (df_mov is not None and not df_mov.empty) else 0.0
        debe_mov = float(pd.to_numeric(df_mov.iloc[0]["debe_mov"], errors="coerce") or 0.0) if (df_mov is not None and not df_mov.empty) else 0.0

        saldo_inicial = haber_si - debe_si
        movimiento_neto_pasivo = haber_mov - debe_mov
        deuda_final = round(saldo_inicial + movimiento_neto_pasivo, 2)

        return deuda_final, fecha_corte


    
    import html
    import io
    import textwrap
    from PIL import Image, ImageDraw, ImageFont
    import pandas as pd
    import streamlit as st


    def _limpiar_html(texto_html: str) -> str:
        return "\n".join(linea.lstrip() for linea in texto_html.splitlines()).strip()


    def generar_png_etiqueta_post(post: dict, etiquetas_sev: dict | None = None) -> bytes:
        """
        Genera una imagen PNG tipo tarjeta/etiqueta a partir de un dict de post,
        incluyendo su etiqueta de estado/severidad en la imagen.
        """
        if etiquetas_sev is None:
            etiquetas_sev = {
                "critico": "CRÍTICO",
                "atencion": "ATENCIÓN",
                "positivo": "AVANCE",
                "info": "DATO",
            }

        sev = str(post.get("severidad", "info")).lower()
        colores_sev = {
            "critico": {"borde": (255, 77, 79), "badge_bg": (66, 24, 28), "badge_fg": (255, 120, 117)},
            "atencion": {"borde": (245, 158, 11), "badge_bg": (64, 45, 14), "badge_fg": (251, 191, 36)},
            "positivo": {"borde": (34, 197, 94), "badge_bg": (18, 56, 34), "badge_fg": (74, 222, 128)},
            "info": {"borde": (88, 166, 255), "badge_bg": (22, 44, 74), "badge_fg": (121, 192, 255)},
        }
        paleta = colores_sev.get(sev, colores_sev["info"])

        ancho, alto = 960, 300
        bg_card = (13, 17, 23)
        bg_linea = (22, 27, 34)
        fg_texto = (240, 246, 252)
        fg_muted = (139, 148, 158)

        img = Image.new("RGB", (ancho, alto), bg_card)
        draw = ImageDraw.Draw(img)

        # Borde izquierdo de severidad
        draw.rectangle([0, 0, 10, alto], fill=paleta["borde"])

        font_cat = ImageFont.load_default()
        font_body = ImageFont.load_default()
        font_foot = ImageFont.load_default()

        categoria = str(post.get("categoria", "General"))
        etiqueta_txt = str(post.get("etiqueta") or etiquetas_sev.get(sev, "DATO")).upper()
        badge = f"{categoria} • {etiqueta_txt}"
        contexto = str(post.get("contexto", ""))
        fecha = str(post.get("fecha", ""))

        # Limpiar etiquetas HTML simples del titular para el PNG
        cuerpo_limpio = (
            str(post.get("titular_html", ""))
            .replace("<span class='hl'>", "")
            .replace('<span class="hl">', "")
            .replace("</span>", "")
            .strip()
        )

        # Encabezado: categoría y etiqueta en la imagen
        draw.text((32, 26), categoria, fill=fg_muted, font=font_cat)
        badge_w = max(110, len(badge) * 8 + 28)
        draw.rounded_rectangle(
            [ancho - 32 - badge_w, 20, ancho - 32, 48],
            radius=12,
            fill=paleta["badge_bg"],
            outline=paleta["borde"],
            width=1,
        )
        draw.text((ancho - 32 - badge_w + 14, 28), badge, fill=paleta["badge_fg"], font=font_body)

        # Cuerpo envuelto en líneas
        lineas = textwrap.wrap(cuerpo_limpio, width=78)
        y_actual = 82
        for linea in lineas[:4]:
            draw.text((32, y_actual), linea, fill=fg_texto, font=font_body)
            y_actual += 28

        # Pie de página
        draw.line([(32, alto - 58), (ancho - 32, alto - 58)], fill=bg_linea, width=1)
        draw.text((32, alto - 40), contexto, fill=fg_muted, font=font_foot)
        fecha_w = len(fecha) * 7
        draw.text((ancho - 32 - fecha_w, alto - 40), fecha, fill=fg_muted, font=font_foot)

        buf = io.BytesIO()
        img.save(buf, format="PNG")
        return buf.getvalue()


    @st.cache_data(show_spinner=False)
    def _png_post_cacheado(post_key: tuple, etiquetas_items: tuple) -> bytes:
        post_dict = {
            "categoria": post_key[0],
            "severidad": post_key[1],
            "etiqueta": post_key[2],
            "titular_html": post_key[3],
            "contexto": post_key[4],
            "fecha": post_key[5],
        }
        return generar_png_etiqueta_post(post_dict, dict(etiquetas_items))


