                    t2.metric("Ventas Exentas", f_bs(df_limpio['ventas_exentas'].sum()))
                    t3.metric("Total Base", f_bs(df_limpio['base_imponible'].sum()))
                    t4.metric("Débito Fiscal", f_bs(df_limpio['debito_fiscal'].sum()))
                    
                    # 8. BOTÓN PROCESAR
